#include <vector>
#include <unordered_map>
using namespace std;
class Solution {
public:
    int sumOfUnique(vector<int>& nums) {
        unordered_map<int, int> counts;
        for (int x : nums) counts[x]++;
        int sum = 0;
        for (auto& p : counts) {
            if (p.second == 1) sum += p.first;
        }
        return sum;
    }
};
